def insertion_sort(lis):
    c = 0
    if len(set(lis)) == 1:
        return c
    i = 1
    curr = len(lis)
    while i < curr:
        k = lis[i]
        j = i - 1
        while j >= 0 and k < lis[j]:
            lis[j + 1] = lis[j]
            j -= 1
            c += 1
        lis[j + 1] = k
        i += 1
    return c

