def buscar(t,ind,let):
    if t[ind] == let:
        return 0,ind
    ci=cd=0
    i=j=ind
    while i>0 and j<len(t):
        if t[i]==let:
            return ci,i
        if t[j]==let:
            return cd,j
        i-=1
        j+=1
        cd+=1
        ci+=1
    if i!=-1:
        if t[i]==let:
            return ci,i
    if j!=len(t):
        if t[j]==let:
            return cd,j
