import sys
from collections import deque
from heapq import *

while 1:
    try:
        N = int(input())
    except:
        break
    stack = []
    queue = deque()
    heap = []
    isStack = isQueue = isHeap = 1
    i = 0
    temp = N
    while i < temp:
        x,y = map(int, input().split())
        if x == 1:
            stack.append(y)
            queue.append(y)
            heappush(heap, -y)
        else:
            a = stack.pop()
            if a != y:
                isStack = 0
            a = queue.popleft()
            if a != y:
                isQueue = 0
            a = -heappop(heap)
            if a != y:
                isHeap = 0
        i += 1
    s = sum([isStack, isQueue, isHeap])
    if s >= 2:
        print ('not sure')
    elif s == 0:
        print ('impossible')
    else:
        if isStack:
            print ('stack')
        if isQueue:
            print ('queue')
        if isHeap:
            print ('priority queue')

