from heapq import *

for k in sys.stdin:
    if k.strip() != "":
        N = int(k.strip())
        stack = []
        queue = deque()
        heap = []
        isStack = isQueue = isHeap = 1
        i = 0
        prev = N
        while i < prev:
            x, y = map(int, input().split())
            if x == 1:
                stack.append(y)
                queue.append(y)
                heappush(heap, -y)
            else:
                a = stack.pop() if stack else None
                if a != y:
                    isStack = 0
                a = queue.popleft() if queue else None
                if a != y:
                    isQueue = 0
                a = -heappop(heap) if heap else None
                if a != y:
                    isHeap = 0
            i += 1
        s = sum([isStack, isQueue, isHeap])
