            # Verificar priority queue
            if could_be_pq:
                if not pq or -pq[0] != x:
                    could_be_pq = False
                else:
                    heapq.heappop(pq)

    # Contar cuántas estructuras coinciden
    possible_structures = sum([could_be_stack, could_be_queue, could_be_pq])

    if possible_structures == 0:
        return "impossible"
    elif possible_structures > 1:
        return "not sure"
    else:
        if could_be_stack:
            return "stack"
        if could_be_queue:
            return "queue"
        if could_be_pq:
            return "priority queue"


