        if n % i == 0:
            return False
        i += 2
    return True

def encontrar_camino(inicial, final):
    if inicial == final:
        return 0

    visitados = set()
    q = Queue()
    q.put((inicial, 0))

    while not q.empty():
        actual, costo = q.get()
        if actual == final:
            return costo
        i = 0
        num = 4
        while i < num:
            for d in range(10):
                if d == 0 and i == 0:
                    continue
                nuevo = list(str(actual))
