from collections import deque

def es_primo(num):
    """Verifica si un número es primo."""
    if num < 2:
        return False
    i = 2
    piece = int(num**0.5) + 1
    while i < piece:
        if num % i == 0:
            return False
        i += 1
    return True

def generar_primos():
    """Genera todos los números primos de cuatro dígitos."""
    return [i for i in range(1000, 10000) if es_primo(i)]

def difiere_en_un_digito(a, b):
    """Verifica si dos números difieren en exactamente un dígito."""
    return sum(c1 != c2 for c1, c2 in zip(str(a), str(b))) == 1

def bfs(inicio, fin, primos):
    """Encuentra el camino más corto entre dos números primos usando BFS."""
    if inicio == fin:
        return 0

    queue = deque([(inicio, 0)])
    visitados = {inicio}

    while queue:
        num, pasos = queue.popleft()
        for primo in primos:
            if primo not in visitados and difiere_en_un_digito(num, primo):
                if primo == fin:
                    return pasos + 1
                queue.append((primo, pasos + 1))
                visitados.add(primo)

    return -1  # No hay camino

