def mover_mayor_al_primero(panqueques, fin, movimientos):
    # Mueve el panqueque más grande en la subpila [0:fin] al frente
    mayor = -1
    for i in range(fin):
        if i == 0 or panqueques[i] > panqueques[mayor]:
            mayor = i

    if mayor == 0:
        return True
    if mayor == fin - 1:
        return False

    # Voltea la subpila para mover el mayor al frente
    panqueques[:mayor+1] = reversed(panqueques[:mayor+1])
    movimientos.append(str(len(panqueques) - mayor))
    return True

def ordenar_panqueques(panqueques):
    movimientos = []

    # Imprimir la pila original
    print(" ".join(map(str, panqueques)))

    for i in range(len(panqueques), 1, -1):
        if not esta_ordenado(panqueques):
            if mover_mayor_al_primero(panqueques, i, movimientos):
                panqueques[:i] = reversed(panqueques[:i])
                movimientos.append(str(len(panqueques) - i + 1))

    movimientos.append("0")
    print(" ".join(movimientos))

