def count_swaps(train):
    n = len(train)
    train_copy = train.copy() 
    swaps = 0
    i = 0
    index = n
    while i < index:
        swapped = False
        for j in range(0, n-i-1):
            if train_copy[j] > train_copy[j+1]:
                train_copy[j], train_copy[j+1] = train_copy[j+1], train_copy[j]
                swaps += 1
                swapped = True
        if not swapped:
            break
        i += 1

    return swaps

