    resultados = []


    for i, pronostico in enumerate(pronosticos):

        if ">=" in pronostico:
            expresion, valor = pronostico.split(">=")
            operador = ">="
        elif "<=" in pronostico:
            expresion, valor = pronostico.split("<=")
            operador = "<="
        elif ">" in pronostico:
            expresion, valor = pronostico.split(">")
            operador = ">"
        elif "<" in pronostico:
            expresion, valor = pronostico.split("<")
            operador = "<"
        elif "=" in pronostico:
            expresion, valor = pronostico.split("=")
            operador = "="
        else:
            raise ValueError("Operador no reconocido en el pronóstico")


        partidos_en_pronostico = expresion.split("+")
        suma = sum(partidos[p.strip()] for p in partidos_en_pronostico)


        valor_comparacion = float(valor.strip())
        if operador == ">=":
            correcto = suma >= valor_comparacion
        elif operador == "<=":
            correcto = suma <= valor_comparacion
        elif operador == ">":
            correcto = suma > valor_comparacion
        elif operador == "<":
            correcto = suma < valor_comparacion
        else:
            correcto = abs(suma - valor_comparacion) < 1e-9 if operador == "=" else False


        if correcto:
            resultados.append(f"Guess #{i + 1} was correct.")
        else:
            resultados.append(f"Guess #{i + 1} was incorrect.")

    return resultados



