    # Leer el primer valor: número de partidos y pronósticos
    primera_linea = input().strip()
    num_partidos, num_pronosticos = map(int, primera_linea.split())

    # Leer los resultados de los partidos y almacenarlos en un diccionario
    resultados = {}
    for _ in range(num_partidos):
        partido, porcentaje = input().strip().split()
        resultados[partido] = float(porcentaje)
    i = 1
    index = num_pronosticos + 1
    while i < index:
        pronostico = input().strip().split()

        # Dividir el pronóstico en expresión y el operador
        expresion = pronostico[:-2]  # Todo excepto los últimos dos elementos
        operador = pronostico[-2]  # El operador (>, <, >=, <=, =)
        valor_comparar = int(pronostico[-1])  # El valor a comparar

        # Calcular el valor de la expresión
        suma = 0.0
        for token in expresion:
            if token in resultados:
                suma += resultados[token]
            elif token == '+':
                continue  # Ignorar el operador de suma

        # Comparar según el operador
        if operador == '>':
            es_correcto = suma > valor_comparar
        elif operador == '<':
            es_correcto = suma < valor_comparar
        elif operador == '>=':
            es_correcto = suma >= valor_comparar
        elif operador == '<=':
            es_correcto = suma <= valor_comparar
        elif operador == '=':
            # Comparación de igualdad considerando precisión de punto flotante
            es_correcto = abs(suma - valor_comparar) < 1e-6
        else:
            raise ValueError("Operador desconocido")

        # Imprimir el resultado
        if es_correcto:
            print(f"Guess #{i} was correct.")
        else:
            print(f"Guess #{i} was incorrect.")
        i += 1

