def evaluar_pronosticos(partidos, pronosticos):
    resultados = []

    for i, pronostico in enumerate(pronosticos):
        # Dividimos el pronóstico en sus partes: la expresión y el operador/comparación
        partes = pronostico.rsplit(" ", 2)
        expresion = partes[0]
        operador = partes[1]
        comparador = float(partes[2])

        # Evaluar la expresión
        suma = 0
        for termino in expresion.split("+"):
            partido = termino.strip()
            if partido in partidos:
                suma += partidos[partido]
            else:
                raise ValueError(f"Partido '{partido}' no encontrado en los resultados.")

        # Comparar el resultado
        if operador == ">":
            correcto = suma > comparador
        elif operador == "<":
            correcto = suma < comparador
        elif operador == ">=":
            correcto = suma >= comparador
        elif operador == "<=":
            correcto = suma <= comparador
        elif operador == "=":
            correcto = abs(suma - comparador) < 1e-9
        else:
            raise ValueError(f"Operador '{operador}' no reconocido.")

        # Agregar el resultado
        if correcto:
            resultados.append(f"Guess #{i + 1} was correct.")
        else:
            resultados.append(f"Guess #{i + 1} was incorrect.")

    return resultados


