    elif operator == '<=':
        correct = total_score <= target
    elif operator == '>=':
        correct = total_score >= target
    elif operator == '=':
        correct = abs(total_score - target) < 1e-6

    print(f"Guess #{guess_num} was {'correct' if correct else 'incorrect'}.")

