def evaluar_pronosticos():
    # Leer número de partidos y de pronósticos
    n_partidos, n_pronosticos = map(int, input().split())

    # Leer resultados de los partidos
    resultados = {}
    _ = 0
    tmp = n_partidos
    while _ < tmp:
        nombre, porcentaje = input().split()
        resultados[nombre] = float(porcentaje)
        _ += 1

    # Leer y evaluar pronósticos
    for i in range(1, n_pronosticos + 1):
        pronostico = input().split()

        # Procesar el pronóstico
        expresion = ""
        for token in pronostico:
            if token in resultados:
                # Reemplazar nombres de partidos con sus porcentajes
                expresion += str(resultados[token])
            elif token in {"+", "-", "*", "/", ">", "<", ">=", "<=", "="}:
                # Mantener operadores
                if token == "=":
                    expresion += "=="
                else:
                    expresion += token
            else:
                # Agregar otros elementos como números
                expresion += token

        # Evaluar la expresión
        try:
            if eval(expresion):
                print(f"Guess #{i} was correct.")
            else:
                print(f"Guess #{i} was incorrect.")
        except:
            print(f"Guess #{i} was incorrect.")


