def analizar_pronosticos():
    import sys
    import re
    entrada = sys.stdin.read().splitlines()

    linea_inicial = entrada[0].split()
    cantidad_partidos, cantidad_pronosticos = int(linea_inicial[0]), int(linea_inicial[1])

    resultados = {}
    i = 1
    aux = cantidad_partidos + 1
    while i < aux:
        datos_partido = entrada[i].split()
        nombre_partido = datos_partido[0]
        porcentaje_obtenido = float(datos_partido[1])
        resultados[nombre_partido] = porcentaje_obtenido
        i += 1

    predicciones = entrada[cantidad_partidos + 1:]
    salida = []

    for indice, prediccion in enumerate(predicciones, start=1):
        partes = re.split(r'(\+|>=|<=|>|<|=)', prediccion.replace(" ", ""))
        suma_calculada = 0.0
        comparador = None
        numero_comparar = 0

        for elemento in partes:
            if elemento in {"+", ">=", "<=", ">", "<", "="}:
                comparador = elemento
            elif elemento.isdigit():
                numero_comparar = int(elemento)
            else:
                suma_calculada += resultados[elemento]

        es_correcto = False
        if comparador == ">":
            es_correcto = suma_calculada > numero_comparar
        elif comparador == "<":
            es_correcto = suma_calculada < numero_comparar
        elif comparador == ">=":
            es_correcto = suma_calculada >= numero_comparar
        elif comparador == "<=":
            es_correcto = suma_calculada <= numero_comparar
        elif comparador == "=":
            es_correcto = abs(suma_calculada - numero_comparar) < 1e-9

        if es_correcto:
            salida.append(f"Guess #{indice} was correct.")
        else:
            salida.append(f"Guess #{indice} was incorrect.")

    print("\n".join(salida))


