def procesar_pronosticos(partidos, pronosticos):
    res = []

    for i, p in enumerate(pronosticos):

        if ">=" in p:
            exp, val = p.split(">=")
            op = ">="
        elif "<=" in p:
            exp, val = p.split("<=")
            op = "<="
        elif ">" in p:
            exp, val = p.split(">")
            op = ">"
        elif "<" in p:
            exp, val = p.split("<")
            op = "<"
        elif "=" in p:
            exp, val = p.split("=")
            op = "="
        else:
            raise ValueError("Operador no reconocido en el pronóstico")

        partidos_exp = exp.split("+")
        suma = sum(partidos[partido.strip()] for partido in partidos_exp)

        val_comp = float(val.strip())
        if op == ">=":
            correcto = suma >= val_comp
        elif op == "<=":
            correcto = suma <= val_comp
        elif op == ">":
            correcto = suma > val_comp
        elif op == "<":
            correcto = suma < val_comp
        elif op == "=":
            correcto = abs(suma - val_comp) < 1e-9  # Comparación precisa de flotantes
        else:
            correcto = False

        if correcto:
            res.append(f"Guess #{i + 1} was correct.")
        else:
            res.append(f"Guess #{i + 1} was incorrect.")

    return res


