def evaluar_pronosticos(partidos, pronosticos):
    resultados = []
    tolerancia = 1e-6  

    for i, pronostico in enumerate(pronosticos):
        izquierda, operador, derecha = None, None, None
        for op in ['>=', '<=', '=', '>', '<']:
            if op in pronostico:
                izquierda, derecha = pronostico.split(op)
                operador = op
                break

        suma = 0.0
        for parte in izquierda.split('+'):
            partido = parte.strip()
            suma += partidos.get(partido, 0.0)
        derecha = float(derecha.strip())

        if operador == '<' and suma < derecha - tolerancia:
            resultados.append(f"Guess #{i + 1} was correct.")
        elif operador == '>' and suma > derecha + tolerancia:
            resultados.append(f"Guess #{i + 1} was correct.")
        elif operador == '<=' and suma <= derecha + tolerancia:
            resultados.append(f"Guess #{i + 1} was correct.")
        elif operador == '>=' and suma >= derecha - tolerancia:
            resultados.append(f"Guess #{i + 1} was correct.")
        elif operador == '=' and abs(suma - derecha) < tolerancia:
            resultados.append(f"Guess #{i + 1} was correct.")
        else:
            resultados.append(f"Guess #{i + 1} was incorrect.")

    return resultados

