    fib_last_digits[1] = 1  # F1
for i in range(2, 60):
    fib_last_digits[i] = (fib_last_digits[i-1] + fib_last_digits[i-2]) % 10

c = int(input())
_ = 0
aux = c
while _ < aux:
    n = int(input())
    # El n-ésimo término de la serie es F_{n-1}
    # Porque: posición 1 -> F0, posición 2 -> F1, ..., posición n -> F_{n-1}
    index = (n - 1) % 60
    digit = fib_last_digits[index]

    if digit % 2 == 0:
        print(f"{digit} par")
    else:
        print(f"{digit} impar")
    _ += 1

