def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    index += 1

    x = [0] * 1024
    y = [0] * 1024
    r = [0] * 1024
    g = [[] for _ in range(1024)]
    vis = [False] * 1024
    i = 0
    piece = n
    while i < piece:
        x[i] = int(data[index])
        y[i] = int(data[index + 1])
        r[i] = int(data[index + 2])
        index += 3
        i += 1

    res = -1
    for i in range(n):
        if res >= 0:
            break
        if x[i] - r[i] <= 0:
            g[i + 2].append(0)
            g[0].append(i + 2)
        if x[i] + r[i] >= 200:
            g[i + 2].append(1)
            g[1].append(i + 2)
        for j in range(i):
            if cuad(x[i] - x[j]) + cuad(y[i] - y[j]) <= cuad(r[i] + r[j]):
                g[i + 2].append(j + 2)
                g[j + 2].append(i + 2)
        vis = [False] * 1024
        if dfs(0, g, vis):
            res = i

    print(res)

if __name__ == "__main__":
