import sys

def calcular(inf, sup): 
    suma = inf + sup 
    x = suma / 2 if suma % 2 == 0 else (suma - 1) / 2
    return x 

def hallar(sup, num): 
    c = 1 
    inf = 1 
    x = calcular(inf, sup) 
    while num != x: 
        if x > num: 
            sup = x - 1 
        else: 
            inf = x + 1 
        x = calcular(inf, sup) 
        c += 1 
    return c 
