def sum_of_digits_decimal(n):
    return sum(int(digit) for digit in str(n))
def sum_of_digits_hexadecimal(n):
    hex_str = format(n, 'X')
    return sum(int(digit, 16) for digit in hex_str)
def sum_of_digits_duodecimal(n):
    duodecimal_digits = []
    while n > 0:
        duodecimal_digits.append(n % 12)
        n //= 12
    return sum(duodecimal_digits)
def main():
    results = []
    num = 1000
    count = 10000
    while num < count:
        sum_dec = sum_of_digits_decimal(num)
        sum_hex = sum_of_digits_hexadecimal(num)
        sum_duo = sum_of_digits_duodecimal(num)
        if sum_dec == sum_hex == sum_duo:
            results.append(num)
        num += 1
    for result in results:
        print(result)
