def encontrar_maxima_ganancia(meses):
    max_ganancia = float('-inf')
    ganancia_actual = 0
    inicio_actual = 0
    mejor_inicio = -1
    mejor_fin = -1
    mejor_longitud = 0
    i = 0
    idx = len(meses)
    while i < idx:
        if ganancia_actual <= 0:
            ganancia_actual = meses[i]
            inicio_actual = i
        else:
            ganancia_actual += meses[i]

        if (ganancia_actual > max_ganancia or
            (ganancia_actual == max_ganancia and (i - inicio_actual > mejor_longitud or
                                                  (i - inicio_actual == mejor_longitud and i > mejor_fin)))):
            max_ganancia = ganancia_actual
            mejor_inicio = inicio_actual
            mejor_fin = i
            mejor_longitud = i - inicio_actual
        i += 1

    if max_ganancia <= 0:
        return (0, -1, -1)
    else:
        return (max_ganancia, mejor_inicio, mejor_fin)

def main():
    while True:
        M = int(input())
        if M == 0:
            break
        meses = list(map(int, input().split()))
        resultado = encontrar_maxima_ganancia(meses)
        print(f"{resultado[0]} {resultado[1]} {resultado[2]}")

