def encontrar_maxima_ganancia(m):
    mg = float('-inf')
    ga = 0
    ia = 0
    mi = -1
    mf = -1
    ml = 0
    i = 0
    cnt = len(m)
    while i < cnt:
        if ga <= 0:
            ga = m[i]
            ia = i
        else:
            ga += m[i]

        if (ga > mg or
            (ga == mg and (i - ia > ml or (i - ia == ml and i > mf)))):
            mg = ga
            mi = ia
            mf = i
            ml = i - ia
        i += 1

    if mg <= 0:
        return (0, -1, -1)
    else:
        return (mg, mi, mf)

def main():
