def formatear_polinomio(coeficientes):
    grado_max = len(coeficientes) - 1
    polinomio = ""

    for i in range(len(coeficientes)):
        coef = coeficientes[i]
        grado = grado_max - i

        if coef == 0:
            continue

        if polinomio and coef > 0:
            polinomio += " + "
        elif coef < 0:
            polinomio += " - "
            coef = -coef

        if grado == 0:
            polinomio += f"{coef}"
        elif grado == 1:
            polinomio += f"{coef if coef != 1 else ''}x"
        else:
            polinomio += f"{coef if coef != 1 else ''}x^{grado}"

    return polinomio or "0"

