def process_text(text):
    from collections import defaultdict
    pair_count = defaultdict(int)
    words = text.split()

    for word in words:
        i = 0
        amount = len(word) - 1
        while i < amount:
            pair = word[i:i+2]
            pair_count[pair] += 1
            i += 1
    filtered_pairs = {pair: count for pair, count in pair_count.items() if count > 3}
    sorted_pairs = sorted(filtered_pairs.items())

    return sorted_pairs

def main():
    import sys
    input = sys.stdin.read
    data = input().strip().split('\n')

    for line in data:
        if line.strip():
            result = process_text(line.strip())
            if result:
                for pair, count in result:
                    print(f"{pair} {count}")
            print("----------")

if __name__ == "__main__":
