def generate_chess_pattern(rows, cols):
    # Crear el tablero
    board = []
    i = 0
    piece = rows
    while i < piece:
        row = []
        for j in range(cols):
            # Si la suma de índices es par, comenzamos con punto
            # Si es impar, comenzamos con X
            if (i + j) % 2 == 0:
                row.append('.')
            else:
                row.append('X')
        board.append(row)
        i += 1

    if board[rows-1][cols-1] == 'X':
        # Si es X, invertimos todo el tablero
        for i in range(rows):
            for j in range(cols):
                board[i][j] = '.' if board[i][j] == 'X' else 'X'

    return board

def print_board(board):
    # Imprimir el tablero
    for row in board:
        print(''.join(row))
    # Imprimir la línea de guiones
    print('-' * 10)

