def generate_prime_rounds(current, is_prime, limit):
    """Generates round prime numbers recursively, checking their validity."""
    if current > limit:
        return 0

    count = 1 if is_prime[current] else 0
    for digit in ['1', '3', '7', '9']:
        next_number = int(str(current) + digit)
        if next_number <= limit:
            count += generate_prime_rounds(next_number, is_prime, limit)

    return count




