def generate_round_primes(limit):
    round_primes = [1, 2, 3, 5, 7]
    queue = [1, 2, 3, 5, 7]

    while queue:
        current = queue.pop(0)
        for digit in [1, 3, 7, 9]:
            new_num = current * 10 + digit
            if new_num > limit:
                continue
            if is_prime(new_num):
                round_primes.append(new_num)
                queue.append(new_num)

