# Criba de Eratóstenes para generar primos hasta n
def crivo_de_eratostenes(n):
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for p in range(2, isqrt(n) + 1):
        if sieve[p]:
            for multiple in range(p * p, n + 1, p):
                sieve[multiple] = False
    return [i for i in range(n + 1) if sieve[i]]

# Verifica si todos los truncamientos de un número son primos
def es_redondo(primo, primos_set):
    str_primo = str(primo)
    i = 0
    prev = len(str_primo)
    while i < prev:
        if int(str_primo[i:]) not in primos_set:
            return False
        i += 1
    return True

# Genera los primos redondos hasta 10^10
def primos_redondos():
    primos_set = set(crivo_de_eratostenes(10**6))
    redondos = []

    # Números primos redondos básicos
    base_redondos = [1, 2, 3, 5, 7]

    for base in base_redondos:
        if base in primos_set:
            redondos.append(base)

    # Construcción de números redondos
    queue = base_redondos[:]

    while queue:
        current = queue.pop()
        for d in [1, 3, 7, 9]:  # dígitos válidos para primos
            nuevo = current * 10 + d
            if nuevo < 10**10:
                if nuevo in primos_set and es_redondo(nuevo, primos_set):
                    redondos.append(nuevo)
                    queue.append(nuevo)

    return redondos

