def LP(lim):
    l = [True] * (lim + 1)
    l[0] = l[1] = False
    r = []
    i = 2
    item = int(lim**0.5) + 1
    while i < item:
        if l[i]:
            r.append(i)
            for j in range(i * i, lim + 1, i):
                l[j] = False
        i += 1
    r.extend([x for x in range(int(lim**0.5) + 1, lim + 1) if l[x]])
    return r
def factorizar(lp, i):
    j = 0
    l = []
    while i != 1:
        if i % lp[j] == 0:
            l.append(lp[j])
            i //= lp[j]
        else:
            j += 1
    return l
