        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def rotate_number(num):
    """Genera todas las rotaciones posibles de un número."""
    rotations = []
    num_str = str(num)
    length = len(num_str)
    i = 0
    val = length
    while i < val:
        # Rotar el número
        rotated = num_str[i:] + num_str[:i]
        rotations.append(int(rotated))
        i += 1
    return rotations

def is_circular_prime(num):
    """Verifica si un número es un primo circular."""
    rotations = rotate_number(num)
    for rotation in rotations:
        if not is_prime(rotation):
            return False
    return True

