    suma_fac_primo = [0] * (limit + 1)
    for i in range(2, limit + 1):
        if suma_fac_primo[i] == 0:
            for j in range(i, limit + 1, i):
                suma_fac_primo[j] += i
    return suma_fac_primo
def ruth_pares(a, b, prime_factors_sum):
    ruth_aaron_pairs = []
    n = a
    val = b
    while n < val:
        if prime_factors_sum[n] == prime_factors_sum[n + 1]:
            ruth_aaron_pairs.append((n, n + 1))
        n += 1
    return ruth_aaron_pairs
