def criba_eratostenes(n):
    is_prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if (is_prime[p]):
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    return [p for p in range(2, n + 1) if is_prime[p]]

def suma_factores_primos_unicos(num, primos):
    suma = 0
    factores = set()

    for p in primos:
        if p * p > num: 
            break
        while num % p == 0:
            factores.add(p)  
            num //= p
    if num > 1:  
        factores.add(num)

    return sum(factores)

