def tiempo_de_espera(cola, posicion):
    tiempo = 0
    while True:
        trabajo = cola.pop(0)
        if any(trabajo < otro for otro in cola):
            cola.append(trabajo)
            if posicion == 0:
                posicion = len(cola) - 1
            else:
                posicion -= 1
        else:
            tiempo += 1
            if posicion == 0:
                return tiempo
            else:
                posicion -= 1

