from collections import deque

def time_to_print(n, m, trabajos):
    queue = deque((i, prioridad) for i, prioridad in enumerate(trabajos))
    pq = []

    while queue:
        ocurrencia = queue.popleft()

        if any(ocurrencia[1] < trabajo[1] for trabajo in queue):
            queue.append(ocurrencia)
        else:
            pq.append(ocurrencia[0])
            if ocurrencia[0] == m:
                return len(pq)

    return -1 

