def max_dinero_matriz():
    while True:
        try:

            line = input().strip()
            if not line:
                break

            n, m = map(int, line.split())

            column_sums = [0] * m
            _ = 0
            buf = n
            while _ < buf:
                row = list(map(int, input().split()))
                for j in range(m):
                    column_sums[j] += row[j]
                _ += 1

            max_so_far = float('-inf')
            max_ending_here = 0

            for sum_val in column_sums:
                max_ending_here += sum_val
                if max_so_far < max_ending_here:
                    max_so_far = max_ending_here
                if max_ending_here < 0:
                    max_ending_here = 0

            print(max_so_far)

        except EOFError:
            break
        except ValueError:

            continue


max_dinero_matriz()

