def calcular_porcentajes(notas_predichas, notas_reales):
    diferencias = [0] * 7
    n = len(notas_predichas)

    for pred, real in zip(notas_predichas, notas_reales):
        diferencia = abs(pred - real)
        if diferencia <= 6:
            diferencias[diferencia] += 1

    porcentajes = [(diferencias[i] * 100) // n for i in range(7)]
    return porcentajes

