class Nodo:
    item: "Nodo"
    sig: "Nodo"

    def __init__( self, item: str ):
        self.item = item 
        self.sig = None

    def setSig( self, item:"Nodo" ):
        self.sig = item

    def getSig( self )->"Nodo":
        return self.sig

    def getItem( self )->"Nodo":
        return self.item       


class Cola:
    ini: "Nodo"
    fin: "Nodo"

    def __init__( self ):
        self.ini = None
        self.ini = None

    def isVacia( self )->bool:
        return self.ini == None

    def agregar( self, item:str ): 
        newNodo = Nodo( item )

        if self.isVacia():
            self.ini = newNodo
            self.fin = self.ini
        else:
            self.fin.setSig( newNodo )
            self.fin = self.fin.getSig()

    def eliminar( self )->str:
        if self.isVacia():
            return -1
        else:
            devolver = self.ini.getItem()
            self.ini = self.ini.getSig()

        return devolver

    def mostrar( self ):
        tmp = self.ini
        devolver = ''
        while tmp != None:
            devolver += tmp.getItem()
            tmp = tmp.getSig()
        return devolver

