def rot(m,a):
    if a==90:
        S = []
        i = 0
        elem = len(m)
        while i < elem:
            L = []
            for l in m:
                L = L + [l[i]]
            S = S + [L[::-1]]
            i += 1
        return S
    elif a==180:
        return rot(rot(m,90),90)
    elif a==270:
        return rot(rot(rot(m,90),90),90)


