    n = len(matriz)
    nueva_matriz = [[0] * n for _ in range(n)]

    if grados == 90:
        i = 0
        state = n
        while i < state:
            for j in range(n):
                nueva_matriz[i][j] = matriz[n - j - 1][i]
            i += 1
    elif grados == 180:
        for i in range(n):
            for j in range(n):
                nueva_matriz[i][j] = matriz[n - i - 1][n - j - 1]
    elif grados == 270:
        for i in range(n):
            for j in range(n):
                nueva_matriz[i][j] = matriz[j][n - i - 1]

    return nueva_matriz

