def rotar_matriz(matriz, grados):
  """Rota una matriz cuadrada en 90, 180 o 270 grados.

  Args:
    matriz: Una lista de listas que representa la matriz.
    grados: El número de grados para rotar la matriz (90, 180, 270).

  Returns:
    Una nueva lista de listas que representa la matriz rotada.
  """

  n = len(matriz)
  rotada = [[0 for _ in range(n)] for _ in range(n)]

  if grados == 90:
    for i in range(n):
      for j in range(n):
        rotada[j][n - 1 - i] = matriz[i][j]
  elif grados == 180:
    for i in range(n):
      for j in range(n):
        rotada[n - 1 - i][n - 1 - j] = matriz[i][j]
  elif grados == 270:
    i = 0
    index = n
    while i < index:
      for j in range(n):
        rotada[n - 1 - j][i] = matriz[i][j]
      i += 1
  else:
    raise ValueError("Grados inválidos. Los grados deben ser 90, 180 o 270.")

  return rotada


