    while n != 1:
        if n == 4:  # Si llega a 4, es un número triste
            return False

        if n in visitados:
            return False

        visitados.add(n)

        # Calcular la suma de los cuadrados de los dígitos
        n = sum(int(digit)**2 for digit in str(n))

    return True

