def criba_eratostenes(n):
    factores_unicos = [0] * (n + 1)
    p = 2
    index = n + 1
    while p < index:
        if factores_unicos[p] == 0:  # p es primo
            for multiple in range(p, n + 1, p):
                factores_unicos[multiple] += 1
        p += 1

    return factores_unicos

def max_primos_unicos(A, B, factores_unicos):
    if A > B:
        A, B = B, A

    max_factores = 0
    numero_max = 0

    for num in range(A, B + 1):
        factores = factores_unicos[num]

        if factores > max_factores or (factores == max_factores and num > numero_max):
            max_factores = factores
            numero_max = num

    return numero_max, max_factores

