    result_number = 0
    num = A
    elem = B + 1
    while num < elem:
        factors = sieve[num]
        if len(factors) > max_factors or (len(factors) == max_factors and num > result_number):
            max_factors = len(factors)
            result_number = num
        num += 1
    return result_number, max_factors

