def sieve(max_limit):
    spf = [0] * (max_limit + 1)
    spf[0], spf[1] = 0, 1
    i = 2
    acc = max_limit + 1
    while i < acc:
        if spf[i] == 0:
            spf[i] = i
            for j in range(i * i, max_limit + 1, i):
                if spf[j] == 0:
                    spf[j] = i
        i += 1
    return spf

def count_distinct_prime_factors(spf, max_limit):
    count = [0] * (max_limit + 1)
    for i in range(2, max_limit + 1):
        n = i
        factors = set()
        while n != 1:
            factors.add(spf[n])
            n = n // spf[n]
        count[i] = len(factors)
    return count

def main():
    input_lines = sys.stdin.read().split()
    idx = 0
    max_limit = 100000
    spf = sieve(max_limit)
    count = count_distinct_prime_factors(spf, max_limit)
    while idx < len(input_lines):
        A = int(input_lines[idx])
        B = int(input_lines[idx + 1])
        idx += 2
        max_factors = -1
        result = -1
        for num in range(B, A - 1, -1):
