    es_primo = [True] * (limite + 1)
    es_primo[0] = es_primo[1] = False
    for i in range(2, int(limite**0.5) + 1):
        if es_primo[i]:
            for j in range(i * i, limite + 1, i):
                es_primo[j] = False
    primos = [i for i in range(2, limite + 1) if es_primo[i]]
    return primos, es_primo
def contar_factores_primos(n, primos):
    factores_distintos = set()
    for p in primos:
        if p * p > n:
            break
        while n % p == 0:
            factores_distintos.add(p)
            n //= p
    if n > 1:
        factores_distintos.add(n)
    return len(factores_distintos)
