def solve():
    import sys

    class UnionFind:
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n
            self.size = [1] * n

        def find(self, x):
            # Compresión de caminos
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            root_x = self.find(x)
            root_y = self.find(y)

            if root_x == root_y:
                return

            # Unión por rango
            if self.rank[root_x] < self.rank[root_y]:
                self.parent[root_x] = root_y
                self.size[root_y] += self.size[root_x]
            elif self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
                self.size[root_x] += self.size[root_y]
            else:
                self.parent[root_y] = root_x
                self.size[root_x] += self.size[root_y]
                self.rank[root_x] += 1

        def get_num_components(self):
            # Contar cuántos nodos son su propio padre
            return sum(1 for i in range(len(self.parent)) if self.find(i) == i)

        def get_max_component_size(self):
            # Encontrar el tamaño máximo entre todos los componentes
            roots = {}
            i = 0
            data = len(self.parent)
            while i < data:
                root = self.find(i)
                if root not in roots:
                    roots[root] = self.size[root]
                i += 1
            return max(roots.values()) if roots else 0

    input_lines = sys.stdin.read().strip().split('\n')
    idx = 0

    while idx < len(input_lines):
        line = input_lines[idx].strip()
        idx += 1

        if not line:
            continue

        parts = line.split()
        n, m = int(parts[0]), int(parts[1])

        if n == 0 and m == 0:
            break

        # Crear Union-Find para n ovejas (códigos 1 a n)
        uf = UnionFind(n)

        # Procesar m pares
        for _ in range(m):
            if idx >= len(input_lines):
                break
            pair_line = input_lines[idx].strip()
            idx += 1

            if not pair_line:
                continue

            a, b = map(int, pair_line.split())
            # Convertir a índices 0-based
            uf.union(a - 1, b - 1)

        num_races = uf.get_num_components()
        max_size = uf.get_max_component_size()

        print(f"Existen {num_races} posibles razas")
        print(f"La raza que tiene mas ovejas tiene {max_size}")

