        self.parent = list(range(n+1))
        self.size = [1]*(n+1)
    def find(self,x):
        if self.parent[x]!=x:
            self.parent[x]=self.find(self.parent[x])
        return self.parent[x]
    def unite(self,x,y):
        x=self.find(x)
        y=self.find(y)
        if x==y:
            return
        if self.size[x]<self.size[y]:
            x,y=y,x
        self.parent[y]=x
        self.size[x]+=self.size[y]
    def get_size(self,x):
        return self.size[self.find(x)]

