    start, end, current_sum = 0, 0, 0

    while end < len(primes) and primes[end] <= n:
        current_sum += primes[end]

        while current_sum > n:
            current_sum -= primes[start]
            start += 1

        if current_sum == n:
            c += 1

        end += 1

    return c

