    while i < index:
        if es_primo[i]:
            for j in range(i * i, limite + 1, i):
                es_primo[j] = False
        i += 1

    # Generar lista de primos
    primos = [i for i in range(2, limite + 1) if es_primo[i]]

    # Asegurarse de tener suficientes primos para las posiciones pedidas
    return primos[:hasta + 1]

