    n = len(vector)
    contador = 0
    i = 0
    entry = n + 1
    while i < entry:

        for subset in combinations(vector, i):

            if sum(subset) == s:
                contador += 1
        i += 1
    return contador

while True:
    try:

        s, n = map(int, input().split())

        vector = list(map(int, input().split()))

        print(contar_subconjuntos(vector, s))
    except EOFError:

        break

