def main():
    while True:
        try:
            # Leer la entrada de la suma buscada y el número de elementos
            entrada = input().strip()
            if entrada == "":  # Salir si la entrada está vacía
                break

            suma_deseada, n = map(int, entrada.split())

            # Leer los elementos del conjunto
            conjunto = list(map(int, input().strip().split()))

            if len(conjunto) != n:
                print(f"Error: Se esperaban {n} elementos, pero se recibieron {len(conjunto)}.")
                continue

            # Contar subconjuntos que suman a la suma deseada
            resultado = contar_subconjuntos(conjunto, suma_deseada)

            # Imprimir el resultado
            print(resultado)

        except ValueError:
            print("Error: Entrada inválida, asegúrate de ingresar números enteros.")
        except EOFError:
            break  # Salir en caso de final inesperado de la entrada

if __name__ == "__main__":
    main()

