def calcular_clave(cadena):
    # Contar las frecuencias de cada letra en la cadena
    frecuencias = {}
    for letra in cadena:
        if letra in frecuencias:
            frecuencias[letra] += 1
        else:
            frecuencias[letra] = 1
    # Encontrar la letra con la frecuencia máxima
    max_frecuencia = max(frecuencias.values())
    return max_frecuencia

