    abecedario = 'ABCDEFGHIJKLMNÑOPQRSTUVWXYZ'
    return abecedario.index(letra) + 1

def obtener_letra_por_valor(valor):
    abecedario = 'ABCDEFGHIJKLMNÑOPQRSTUVWXYZ'
    if 1 <= valor <= 27:
        return abecedario[valor - 1]
    return ''

def desplazar_letra(letra, desplazamiento):
    valor_actual = obtener_valor_letra(letra)
    nueva_posicion = (valor_actual + desplazamiento - 1) % 27 + 1
    return obtener_letra_por_valor(nueva_posicion)

