from collections import deque

def puede_llegar(N, inicio, fin, mapa):
    if mapa[inicio[0]][inicio[1]] == 'B' or mapa[fin[0]][fin[1]] == 'B':
        return False

    direcciones = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    visitado = [[False] * N for _ in range(N)]
    visitado[inicio[0]][inicio[1]] = True

    cola = deque([(inicio[0], inicio[1])])

    while cola:
        x, y = cola.popleft()

        if (x, y) == (fin[0], fin[1]):
            return True

        for dx, dy in direcciones:
            nuevo_x, nuevo_y = x + dx, y + dy

            if (0 <= nuevo_x < N and 
                0 <= nuevo_y < N and 
                not visitado[nuevo_x][nuevo_y] and 
                mapa[nuevo_x][nuevo_y] == 'L'):

                visitado[nuevo_x][nuevo_y] = True
                cola.append((nuevo_x, nuevo_y))

    return False

def main():
    while True:
        try:

            entrada = input().strip()
            if not entrada:  
                continue

            N = int(entrada)
            if N == 0:  
                break

            xo, yo, xf, yf = map(int, input().strip().split())

            mapa = []
            _ = 0
            amount = N
            while _ < amount:
                fila = list(input().strip())
                mapa.append(fila)
                _ += 1

            if puede_llegar(N, (xo, yo), (xf, yf), mapa):
                print("HAY RUTA POSIBLE")
            else:
                print("NO HAY RUTA POSIBLE")

        except EOFError: 
            break
        except ValueError:
            continue

if __name__ == "__main__":
