def solve(casos):
    ans=[]
    for caso in casos:
        a,b,c=caso
        if a==b==c:
            ans.append((a,0,0))
        else:

            m1=min(a,b,c)
            a-=m1; b-=m1; c-=m1

            x,y=0,0
            if a==0:
                x,y=(b,c)
            elif b==0:
                x,y=(a,c)
            elif c==0:
                x,y=(a,b)

            m2=min(x,y)
            x-=m2; y-=m2

            z=0
            if x==0:
                z=y
            elif y==0:
                z=x
            m3=z

            ans.append((m1,m2,m3))
    for e in ans:
        print(f'{e[0]} {e[1]} {e[2]}')

