    two_ingredient_burgers = 0
    one_ingredient_burgers = 0

    while ingredients[0] > 0 and ingredients[1] > 0 and ingredients[2] > 0:
        three_ingredient_burgers += 1
        ingredients = (ingredients[0] - 1, ingredients[1] - 1, ingredients[2] - 1)

    while (ingredients[0] > 0 and ingredients[1] > 0) or (ingredients[0] > 0 and ingredients[2] > 0) or (ingredients[1] > 0 and ingredients[2] > 0):
        if ingredients[0] > 0 and ingredients[1] > 0:
            two_ingredient_burgers += 1
            ingredients = (ingredients[0] - 1, ingredients[1] - 1, ingredients[2])
        elif ingredients[0] > 0 and ingredients[2] > 0:
            two_ingredient_burgers += 1
            ingredients = (ingredients[0] - 1, ingredients[1], ingredients[2] - 1)
        elif ingredients[1] > 0 and ingredients[2] > 0:
            two_ingredient_burgers += 1
            ingredients = (ingredients[0], ingredients[1] - 1, ingredients[2] - 1)

    one_ingredient_burgers = ingredients[0] + ingredients[1] + ingredients[2]

    return (three_ingredient_burgers, two_ingredient_burgers, one_ingredient_burgers)


