    tmp = int(n ** 0.5) + 1
    while i < tmp:
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
        i += 1
    return divisors

def count_common_divisors(a, b):
    div_a = get_divisors(a)
    div_b = get_divisors(b)
    return len(div_a.intersection(div_b))

def count_faulty_sums(a, b):
    faulty_count = 0
    for x in range(1, a + 1):
        for y in range(x + 1, b + 1):
            if count_common_divisors(x, y) == 1:
                faulty_count += 1
    return faulty_count

def main():
    n = int(input())
    for _ in range(n):
        a, b = map(int, input().split())
        result = count_faulty_sums(a, b)
        print(result)

if __name__ == "__main__":
    main()

