import sys

def has_cycle(graph):
    stack = []
    visited = set()
    on_stack = set()

    def dfs(node):
        if node in on_stack:
            return True
        if node in visited:
            return False

        visited.add(node)
        on_stack.add(node)
        stack.append(node)

        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True

        on_stack.remove(node)
        stack.pop()
        return False

    for node in graph:
        if dfs(node):
            return True

    return False

def main():
    for line in sys.stdin:
        nroCasos = int(line)
        i = 0
        state = nroCasos
        while i < state:
            nodos, arcos = map(int, sys.stdin.readline().split())
            graph = {}
            for _ in range(arcos):
                u, v = map(int, sys.stdin.readline().split())
                if u not in graph:
                    graph[u] = []
                graph[u].append(v)

            if has_cycle(graph):
                sys.stdout.write("Tiene Ciclo\n")
            else:
                sys.stdout.write("No Tiene\n")
            i += 1

main()

