def criba_eratostenes(limite):
    primos = []
    es_primo = [True] * (limite + 1)
    es_primo[0] = es_primo[1] = False
    for num in range(2, int(limite ** 0.5) + 1):
        if es_primo[num]:
            for multiplo in range(num * num, limite + 1, num):
                es_primo[multiplo] = False
    num = 2
    curr = limite + 1
    while num < curr:
        if es_primo[num]:
            primos.append(num)
        num += 1
    return primos

