def factorizar_factorial(n):
    factorial = 1
    for i in range(2, n + 1):
        factorial *= i
    factorizacion = {}
    divisor = 2
    while factorial > 1:
        exponente = 0
        while factorial % divisor == 0:
            exponente += 1
            factorial //= divisor
        if exponente > 0:
            factorizacion[divisor] = exponente
