# Función para generar el enésimo número de Fibonacci
def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    _ = 2
    num = n + 1
    while _ < num:
        a, b = b, a + b
        _ += 1
    return b

# Función para verificar si un número es primo (versión exacta para números pequeños)
def es_primo(n):
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    for i in range(5, isqrt(n) + 1, 6):
        if n % i == 0 or n % (i + 2) == 0:
            return False
    return True

# Test de primalidad probabilístico (Miller-Rabin) para números grandes
def miller_rabin(n, k=5):
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    # Encontrar d tal que n-1 = 2^r * d con d impar
    d, r = n - 1, 0
    while d % 2 == 0:
        d //= 2
        r += 1

    # Realizar k pruebas
    from random import randrange
    for _ in range(k):
        a = randrange(2, n - 1)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

# Función principal
def verificar_fibonacci_primo(n):
    fib_n = fibonacci(n)
    if n <= 50:
        # Para posiciones menores o iguales a 50, prueba exacta de primalidad
        if es_primo(fib_n):
            return "Es primo"
        else:
            return "No es primo"
    else:
        # Para posiciones mayores a 50, usamos el test probabilístico
        if miller_rabin(fib_n):
            return "Probablemente sea primo"
        else:
            return "No es primo"

