    mov = 0
    Y = [y-1, y+1, y, y]
    X = [x, x, x+1, x-1]
    i = 0
    idx = 4
    while i < idx:
        if 0<=X[i]<len(l[0]) and 0<=Y[i]<len(l):
            if not (X[i], Y[i]) in tuplas:
                if l[Y[i]][X[i]]=='.':
                    # print((X[i], Y[i]))
                    tuplas.append((X[i], Y[i]))
                    mov += 1 + search(l, X[i], Y[i], tuplas)
        i += 1
    return mov
