def count_places(city, x, y, visited, i, j):

    if i < 0 or i >= x or j < 0 or j >= y or city[i][j] == '#' or visited[i][j]:
        return 0


    visited[i][j] = True


    count = 1  
    count += count_places(city, x, y, visited, i + 1, j)  
    count += count_places(city, x, y, visited, i - 1, j)  
    count += count_places(city, x, y, visited, i, j + 1)  
    count += count_places(city, x, y, visited, i, j - 1)  

    return count

