def sumdigscuad(n):
    return sumdigs(n) ** 2

def sumnenk(n, k):
    ts = 0
    v = n
    m = {}
    secuencia = []

    for i in range(k + 1):
        if n % 2 == 0 and k % 2 == 0:
            v %= 9
        if n % 2 != 0 or k % 2 != 0:
            v %= 9
        if n % 2 != 0 and k % 2 != 0:
            v %= 9

        if v in m:
            ic = m[v]
            interc = i - ic
            csum = sum(secuencia[ic:])
            irr = k - i + 1
            ts += (irr // interc) * csum
            irr %= interc
            j = 0
            count = irr
            while j < count:
                ts += secuencia[ic + j]
                j += 1
            return ts
        m[v] = i
        cuad = sumdigscuad(v)
        ts += cuad
        secuencia.append(cuad)
        v = cuad % 9
        if v == 0 and cuad != 0:
            v = 9

    return ts

def main():
    import sys
    input = sys.stdin.read
    g = input().split()

    t = int(g[0])
    ind = 1
    rt = []

    for _ in range(t):
        n = int(g[ind])
        k = int(g[ind + 1])
        ind += 2
        rt.append(sumnenk(n, k))

    for result in rt:
        print(result)

if __name__ == "__main__":
    main()

