    bin_rep = bin(N)[2:]

    # Convertir el número N a una cadena
    n_str = str(N)

    # Recorrer cada bit del binario
    for bit in bin_rep:
        if bit == '1':
            n_str = rotate_left(n_str)  # Rotar a la izquierda
