    bin_rep = bin(N)[2:]

    # Convertir el número N a una cadena
    n_str = str(N)

    # Recorrer cada bit del binario
    for bit in bin_rep:
        n_str = rotate_left(n_str) if bit == '1' else rotate_right(n_str)

    return int(n_str)

def main():
    # Leer el número de casos
    C = int(input())

    # Para cada caso, procesar el número N
    for _ in range(C):
        N = int(input())
        result = process_case(N)
        print(result)

