    return dp[n]
def multiplicar_matrix(A, B):
    global mod
    C = [[0, 0], [0, 0]]

    n = len(A)
    for i in range(n):
        for j in range(n):
            k = 0
            cnt = n
            while k < cnt:
                C[i][j] += A[i][k] * B[k][j]
                C[i][j] %= mod
                k += 1
    return C


