def es_primo(n):
    if n <= 1:
        return False
    i = 2
    item = int(n ** 0.5) + 1
    while i < item:
        if n % i == 0:
            return False
        i += 1
    return True

def es_feliz(n):
    visitados = set()
    while n != 1 and n not in visitados:
        visitados.add(n)
        n = sum(int(digit) ** 2 for digit in str(n))
    return n == 1

def main():
    n = int(input().strip())
    if es_primo(n):
        if es_feliz(n):
            print("Primo Feliz")
        else:
            print("Primo Infeliz")
    else:
        print("No es Primo")

if __name__ == "__main__":
    main()

