def encontrar_potencia(a, b, c):
    producto = a * b * c
    mejor_x = -1
    mejor_y = -1

    for x in range(2, int(math.sqrt(producto)) + 1):
        y = 1
        resultado = x
        while resultado < producto:
            y += 1
            resultado *= x
        if resultado == producto:
            if x > mejor_x:
                mejor_x, mejor_y = x, y

    if mejor_x == -1:
        return "-1"
    else:
        return f"{a}*{b}*{c}={producto}={mejor_x}**{mejor_y}"

