def contar_primos_en_rango(a, b):
    # Función auxiliar para generar una lista de números primos hasta b usando el método de la criba de Eratóstenes
    es_primo = [True] * (b + 1)
    es_primo[0] = es_primo[1] = False
    i = 2
    prev = int(b**0.5) + 1
    while i < prev:
        if es_primo[i]:
            for j in range(i * i, b + 1, i):
                es_primo[j] = False
        i += 1
    # Contar los primos en el rango [a, b]
    return sum(1 for i in range(a, b + 1) if es_primo[i])

