    return int(''.join(map(str, lista)))

def obtener_menor_y_mayor(numero):
    lista_digitos = convertir_a_lista(numero)
    lista_ordenada = sorted(lista_digitos)
    menor = convertir_a_entero(lista_ordenada)
    mayor = convertir_a_entero(lista_ordenada[::-1])
    return menor, mayor

def calcular_iteraciones(numero_inicial):
    conjunto_resultados = set()
    iteraciones = 0
    numero_actual = numero_inicial
    if len(set(str(numero_inicial))) == 1:
        return 1, 0
    while True:
        menor, mayor = obtener_menor_y_mayor(numero_actual)
        diferencia = mayor - menor
        iteraciones += 1
        if diferencia in conjunto_resultados:
            return iteraciones - 1, diferencia
        if diferencia == numero_actual:
            return iteraciones, diferencia
        conjunto_resultados.add(diferencia)
        numero_actual = diferencia
        if iteraciones > 100:
            return -1, -1

